import{c as t,Q as o,j as r,m as i}from"./chunks/framework.BPKcPtvA.js";const h=JSON.parse('{"title":"Import Demo Content Manually","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/import-demo-content-manually.md","filePath":"getting-started/import-demo-content-manually.md"}'),a={name:"getting-started/import-demo-content-manually.md"};function n(s,e,l,m,d,p){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="import-demo-content-manually" tabindex="-1">Import Demo Content Manually <a class="header-anchor" href="#import-demo-content-manually" aria-label="Permalink to &quot;Import Demo Content Manually&quot;">​</a></h1><p>If you want to import the demo data manually, or if your theme doesn&#39;t offer the one-click import feature, you can import demo content using the WordPress Importer tool.</p><p>In your theme package you will find a link to download the demo data files. Download, extract the zip and you will find these files:</p><ul><li><code>content.xml</code> — all pages, media, etc.</li><li><code>customizer.dat</code> — the customizer settings.</li><li><code>widgets.wie</code> — the widget settings.</li></ul><h2 id="import-the-content" tabindex="-1">Import the Content <a class="header-anchor" href="#import-the-content" aria-label="Permalink to &quot;Import the Content&quot;">​</a></h2><ol><li>In your admin panel go to <strong>Tools &gt; Import</strong>.</li><li>Choose the <strong>WordPress</strong> option (last one in the list).</li><li>Select the <code>content.xml</code> file.</li><li>Click <strong>Upload file and import</strong> and follow the instructions.</li></ol><blockquote><p><strong>Note:</strong> Some demo data files are large. If you encounter issues, check your <a href="./../general/server-requirements.html">Server Requirements</a> — particularly <code>max_execution_time</code>, <code>post_max_size</code> and <code>upload_max_filesize</code>.</p></blockquote><p><strong>Recommended:</strong> The <a href="http://github.com/humanmade/WordPress-Importer" target="_blank" rel="noreferrer">WordPress Importer v2</a> plugin works better than the default importer, especially on <a href="./../general/low-budget-hosts.html">low settings servers</a>. Deactivate the default WordPress Importer and install this one instead.</p><blockquote><p>During import with WordPress Importer v2, even if the progress bar doesn&#39;t move, wait until it confirms the posts have been imported.</p></blockquote><h3 id="wordpress-importer-v2-and-elementor" tabindex="-1">WordPress Importer v2 and Elementor <a class="header-anchor" href="#wordpress-importer-v2-and-elementor" aria-label="Permalink to &quot;WordPress Importer v2 and Elementor&quot;">​</a></h3><p>If you are using Elementor, use this two-step approach to avoid import issues:</p><ol><li>Use the default <strong>WordPress Importer</strong> to import content <strong>without media</strong> (uncheck the import media option).</li><li>Then use <strong>WordPress Importer v2</strong> to import the media using the same <code>content.xml</code> file (or the <code>medias.xml</code> file if included in the demo package).</li></ol><h2 id="import-the-customizer-settings" tabindex="-1">Import the Customizer Settings <a class="header-anchor" href="#import-the-customizer-settings" aria-label="Permalink to &quot;Import the Customizer Settings&quot;">​</a></h2><p>Customizer settings are applied automatically on theme activation. If you need to reset or import a specific demo&#39;s settings, install the <a href="https://wordpress.org/plugins/customizer-export-import/" target="_blank" rel="noreferrer">Customizer Export/Import</a> plugin.</p><ol><li>Go to <strong>Appearance &gt; Customize</strong>.</li><li>Navigate to the <strong>Export/Import</strong> tab.</li><li>Click <strong>Browse</strong> and select the <code>customizer.dat</code> file.</li><li>Click <strong>Import</strong>.</li></ol><h2 id="import-the-widgets" tabindex="-1">Import the Widgets <a class="header-anchor" href="#import-the-widgets" aria-label="Permalink to &quot;Import the Widgets&quot;">​</a></h2><p>To import widget settings, install the <a href="https://wordpress.org/plugins/widget-importer-exporter/" target="_blank" rel="noreferrer">Widget Importer &amp; Exporter</a> plugin.</p><ol><li>Go to <strong>Tools &gt; Widget Importer &amp; Exporter</strong>.</li><li>Select the <code>widgets.wie</code> file.</li><li>Click <strong>Import</strong>.</li></ol><hr><p><strong>Want to skip the hassle? <a href="https://wolfthemes.com/services/" target="_blank" rel="noreferrer">Explore our setup services</a></strong></p>',20)])])}const g=t(a,[["render",n]]);export{h as __pageData,g as default};
